<template>
  <div class="storefront">
    <header class="topbar">
      <a class="brand" href="/"><span class="brand-mark">S</span><span>SteamDeals<small>游戏价格情报</small></span></a>
      <div class="top-actions"><span v-if="user" class="user-label">{{ user.display_name || user.username }}</span><el-button v-if="!user" plain @click="loginVisible = true">登录</el-button><el-button v-else plain @click="logout">退出</el-button><el-button v-if="user?.role === 'admin'" type="primary" @click="router.push('/console')">管理后台</el-button></div>
    </header>
    <main class="store-main">
      <section class="hero">
        <div><div class="eyebrow">DISCOVER YOUR NEXT GAME</div><h1>好游戏，等个好价格。</h1><p>聚合 Steam 与授权平台报价，快速找到值得入手的折扣。</p></div>
        <div class="catalog-stat"><strong>{{ total.toLocaleString() }}</strong><span>款在售游戏</span></div>
      </section>
      <div class="notice-list"><el-alert v-for="notice in pagedNotices" v-show="!noticeDismissed.has(notice.id)" :key="notice.id" :title="notice.title" :description="notice.body" :type="notice.level === 'critical' ? 'error' : notice.level === 'warning' ? 'warning' : 'info'" show-icon :closable="true" class="notice" @close="dismissNotice(notice.id)" /><PaginationBar v-model:page="noticesPage" v-model:page-size="noticesPageSize" :total="notices.length"/></div>
      <section class="store-tabs"><button v-for="tab in tabs" :key="tab.value" :class="{on:activeTab===tab.value}" @click="setTab(tab.value)">{{ tab.label }}</button></section>
      <p v-if="!user" class="flag-hint">未登录时的标记只保存在此浏览器；登录后以账号数据库中的标记为准。</p>
      <section class="toolbar">
        <el-input v-model="query" clearable placeholder="搜索中文名、英文名或 AppID" class="search" @keyup.enter="loadGames(1)"><template #prefix><el-icon><Search /></el-icon></template></el-input>
        <el-select v-model="region" aria-label="地区" @change="changeRegion"><el-option v-for="r in regions" :key="r.code" :label="r.label" :value="r.code" /></el-select>
        <el-select v-model="type" aria-label="游戏类型" @change="loadGames(1)"><el-option label="全部类型" value="all"/><el-option label="游戏" value="game"/><el-option label="DLC" value="dlc"/></el-select>
        <el-select v-model="sort" aria-label="排序" @change="changeSort"><el-option label="折扣优先" value="discount"/><el-option label="价格优先" value="price"/><el-option label="名称排序" value="name"/></el-select>
        <el-button :loading="loading" @click="loadGames(page)">刷新</el-button>
      </section>
      <div class="result-line"><span>{{ loading ? '正在加载游戏…' : `找到 ${total.toLocaleString()} 款游戏` }}</span><span>价格与地区货币以商店显示为准</span></div>
      <el-skeleton v-if="loading && !games.length" :rows="6" animated />
      <el-empty v-else-if="!games.length" description="没有找到匹配的游戏" />
      <section v-else class="game-grid">
        <article v-for="game in games" :key="game.game_id || game.id" class="game-card" @click="openDetail(game)">
          <div class="cover-wrap"><img :src="cover(game)" :alt="game.name" loading="lazy" decoding="async" fetchpriority="low" @error="fallbackImage"/><span v-if="discount(game)" class="discount">-{{ discount(game) }}%</span></div>
          <div class="game-info"><div class="game-title" :title="game.name">{{ game.name }}</div><div v-if="game.name_en && game.name_en !== game.name" class="game-subtitle">{{ game.name_en }}</div>
            <div class="price-row"><div><strong>{{ money(game.current_low, game.currency) }}</strong><del v-if="game.current_original > game.current_low">{{ money(game.current_original, game.currency) }}</del></div><el-tag v-if="game.prev_hist_low != null && game.current_low < game.prev_hist_low" size="small" type="success" effect="plain">新史低</el-tag><el-tag v-if="game.owned" size="small" type="warning">已拥有</el-tag><el-tag v-else-if="game.interested===false" size="small" effect="plain">不感兴趣</el-tag></div>
            <div class="card-foot"><span>{{ game.low_platform_name || 'Steam' }}</span><a v-if="game.steam_appid" :href="`https://store.steampowered.com/app/${game.steam_appid}/`" target="_blank" rel="noopener" @click.stop>Steam 商店 ↗</a></div>
            <div class="card-flags" @click.stop>
              <el-button size="small" :type="game.interested === true ? 'primary' : 'default'" :plain="game.interested !== true" @click="toggleGameFlag(game, 'interested')">{{ game.interested === true ? '不感兴趣' : '感兴趣' }}</el-button>
              <el-button size="small" :type="game.owned ? 'warning' : 'default'" :plain="!game.owned" @click="toggleGameFlag(game, 'owned')">{{ game.owned ? '取消已拥有' : '已拥有' }}</el-button>
            </div>
          </div>
        </article>
      </section>
      <div class="pagination"><el-pagination v-if="pages > 1" background layout="prev, pager, next, sizes" :total="total" :page-size="pageSize" :current-page="page" :page-sizes="[20,50,100]" @current-change="loadGames" @size-change="changePageSize" /></div>
      <footer class="store-footer">价格信息仅供参考，实际售价以商店结算页面为准。</footer>
    </main>
    <el-dialog v-model="detailVisible" :title="detail?.game?.name||'游戏详情'" width="850px" class="detail-dialog"><div v-if="detailLoading" class="detail-loading">正在加载游戏详情…</div><template v-else-if="detail?.game"><img v-if="detail.game.steam_appid" class="detail-cover" :src="`/img/steam/${detail.game.steam_appid}/header`" @error="fallbackImage"><p class="detail-en">{{ detail.game.name_en }}</p><div class="detail-metrics"><span>当前最低 <strong>{{ money(detail.game.current_low,detail.game.currency) }}</strong></span><span>历史最低 <strong>{{ money(detail.game.hist_low,detail.game.currency) }}</strong></span><span>折扣 <strong>{{ discount(detail.game) }}%</strong></span></div><p class="detail-description">{{ detail.game.description||'暂无游戏介绍。' }}</p><div class="detail-actions"><el-button @click="toggleFlag('interested')">{{ isInterested(detail.game)?'标记不感兴趣':'标记感兴趣' }}</el-button><el-button @click="toggleFlag('owned')">{{ detail.game.owned?'取消已拥有':'标记已拥有' }}</el-button></div><div v-if="user?.role==='admin'" class="detail-actions"><el-input v-model="watchTarget" placeholder="目标价（元，留空为史低提醒）"/><el-button type="primary" @click="saveWatch">{{ watchExists?'更新到价提醒':'添加到价提醒' }}</el-button><el-button v-if="watchExists" @click="deleteWatch">取消提醒</el-button></div><h3>各区服与平台报价</h3><div class="offer-list"><div v-for="offer in pagedOffers" :key="`${offer.region}-${offer.platform_code}-${offer.price_cents}`" class="offer-row"><span>{{ regionName(offer.region) }}</span><strong>{{ offer.platform_name||offer.platform_code }}</strong><span>{{ money(offer.price_cents,offer.currency) }}</span><del>{{ money(offer.original_cents,offer.currency) }}</del><el-tag v-if="offer.discount_pct" size="small" type="danger">-{{ offer.discount_pct }}%</el-tag><a v-if="offer.buy_url" :href="offer.buy_url" target="_blank" rel="noopener noreferrer nofollow">购买 ↗</a></div><el-empty v-if="!detail.offers?.length" description="当前没有在售报价"/></div><PaginationBar v-model:page="offersPage" v-model:page-size="offersPageSize" :total="detail.offers?.length||0"/><h3>价格历史</h3><div class="series-list"><div v-for="point in pagedSeries" :key="point.day"><span>{{ point.day }}</span><strong>{{ money(point.price_cents,point.currency) }}</strong></div></div><PaginationBar v-model:page="seriesPage" v-model:page-size="seriesPageSize" :total="detail.series?.length||0"/><a v-if="detail.game.steam_appid" :href="`/api/games/${detail.game.steam_appid}/history.csv?days=90`" target="_blank">导出 90 天价格历史 CSV</a></template></el-dialog>
    <el-dialog v-model="loginVisible" title="登录 SteamDeals" width="410px" @opened="loginMode==='password'&&loadCaptcha()"><div class="login-modes"><button :class="{on:loginMode==='password'}" @click="loginMode='password';loadCaptcha()">密码登录</button><button :class="{on:loginMode==='email'}" @click="loginMode='email'">邮箱验证码</button><button v-if="loginMode==='reset'" class="on">重置密码</button></div><el-form v-if="loginMode==='password'" @submit.prevent="login"><el-form-item><el-input v-model="username" placeholder="用户名" autocomplete="username" /></el-form-item><el-form-item><el-input v-model="password" placeholder="密码" type="password" show-password autocomplete="current-password" /></el-form-item><div class="captcha-row"><img :src="captchaImage" alt="登录验证码，点击刷新" title="点击刷新验证码" @click="loadCaptcha"><el-input v-model="captchaAnswer" placeholder="验证码" maxlength="6" autocomplete="off" @keyup.enter="login" /></div><a class="login-help" @click="loginMode='reset'">忘记密码？</a><el-button type="primary" class="login-submit" :loading="loginLoading" @click="login">登录</el-button></el-form><el-form v-else @submit.prevent="verifyEmail"><el-form-item><el-input v-model="email" placeholder="账号绑定的邮箱" autocomplete="email" /></el-form-item><div class="email-code-row"><el-input v-model="emailCode" placeholder="6 位验证码" maxlength="6"/><el-button :disabled="codeCooldown>0" @click="requestEmailCode">{{ codeCooldown?`${codeCooldown}s 后重发`:'发送验证码' }}</el-button></div><el-form-item v-if="loginMode==='reset'"><el-input v-model="newPassword" placeholder="新密码（8–200 位）" type="password" show-password autocomplete="new-password"/></el-form-item><el-alert v-if="loginError" :title="loginError" type="error" :closable="false"/><el-button type="primary" class="login-submit" :loading="loginLoading" @click="verifyEmail">{{ loginMode==='reset'?'重置密码':'验证码登录' }}</el-button><a v-if="loginMode==='email'" class="login-help" @click="loginMode='reset'">忘记密码？</a></el-form><el-alert v-if="loginError&&loginMode==='password'" :title="loginError" type="error" :closable="false"/></el-dialog>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import PaginationBar from '../components/PaginationBar.vue';
import { useListPagination } from '../composables/useListPagination.js';
import { useRouter } from 'vue-router';
import { Search } from '@element-plus/icons-vue';
import { ElMessage } from 'element-plus';

const router = useRouter();
const regions = [{code:'cn',label:'中国大陆'},{code:'hk',label:'中国香港'},{code:'tw',label:'中国台湾'},{code:'us',label:'美国'},{code:'jp',label:'日本'},{code:'ru',label:'俄罗斯'},{code:'tr',label:'土耳其'},{code:'ar',label:'阿根廷'}];
const tabs=[{value:'all',label:'全部'},{value:'on',label:'感兴趣'},{value:'off',label:'不感兴趣'},{value:'owned',label:'已拥有'}];
const games = ref([]), notices = ref([]), total = ref(0), pages = ref(0), page = ref(1), pageSize = ref(20), loading = ref(false);
const noticesPager=useListPagination(notices), pagedNotices=noticesPager.items, noticesPage=noticesPager.page, noticesPageSize=noticesPager.pageSize;
const query = ref(''), region = ref('cn'), type = ref('all'), sort = ref('discount'), activeTab=ref('all'), user = ref(null), guestGameFlags=ref({});
const guestFlagsStorageKey='steamdeals.guest-game-flags.v1';
const loginVisible = ref(false), loginMode=ref('password'), username = ref(''), password = ref(''), email=ref(''),emailCode=ref(''),newPassword=ref(''),codeCooldown=ref(0),captchaAnswer=ref(''),captchaToken=ref(''),captchaImage=ref(''), loginError = ref(''), loginLoading = ref(false);
const detailVisible=ref(false),detailLoading=ref(false),detail=ref(null),watchTarget=ref(''),watchExists=ref(false);
const offersPager=useListPagination(computed(()=>detail.value?.offers||[])), seriesPager=useListPagination(computed(()=>[...(detail.value?.series||[])].reverse()));
const pagedOffers=offersPager.items,offersPage=offersPager.page,offersPageSize=offersPager.pageSize,pagedSeries=seriesPager.items,seriesPage=seriesPager.page,seriesPageSize=seriesPager.pageSize;
const noticeDismissed=ref(new Set());let cooldownTimer=null,gameRequestController=null;
function money(cents, currency) { if (cents == null) return '暂无报价'; const symbols={CNY:'¥',USD:'$',HKD:'HK$',TWD:'NT$',JPY:'¥',RUB:'₽',TRY:'₺',ARS:'$'}; const fallback={cn:'CNY',hk:'HKD',tw:'TWD',us:'USD',jp:'JPY',ru:'RUB',tr:'TRY',ar:'ARS'}[region.value]||'CNY';const code=currency||fallback;return `${symbols[code] || code+' '}${(Number(cents)/100).toFixed(2)}`; }
function discount(g) { return Number(g.discount) || 0; }
function cover(g) { return g.steam_appid ? `/img/steam/${g.steam_appid}/header` : '/favicon.svg'; }
function fallbackImage(event) { event.target.src='/favicon.svg'; }
async function request(path, options) { const res=await fetch(path,{credentials:'same-origin',...options,headers:{'content-type':'application/json',...(options?.headers||{})}}); const raw=await res.text(); let data={}; try{data=raw?JSON.parse(raw):{}}catch{} if(!res.ok) throw new Error(data.error||`请求失败 (${res.status})`); return data; }
function localFlagIds(field,value){return Object.entries(guestGameFlags.value).filter(([,flags])=>flags?.[field]===value).map(([id])=>id).filter((id)=>/^\d{1,19}$/.test(id));}
function visibleGames(rows){if(user.value)return rows;return rows.map((game)=>{const flags=guestGameFlags.value[String(game.id)]||{};return {...game,interested:typeof flags.interested==='boolean'?flags.interested:null,owned:flags.owned===true};});}
async function loadGames(nextPage=1){gameRequestController?.abort();const controller=new AbortController();gameRequestController=controller;loading.value=true;page.value=nextPage;const params={page:page.value,pageSize:pageSize.value,region:region.value,type:type.value,sort:sort.value,q:query.value.trim(),interest:activeTab.value==='on'?'on':activeTab.value==='off'?'off':'all',owned:activeTab.value==='owned'?'only':'exclude'};try{const flags={interestedIds:activeTab.value==='on'?localFlagIds('interested',true):[],uninterestedIds:activeTab.value==='off'?localFlagIds('interested',false):[],ownedIds:localFlagIds('owned',true)};const options=user.value?params:{...params,guestFlags:flags};const data=await request('/api/games/search',{method:'POST',body:JSON.stringify(options),signal:controller.signal});if(controller.signal.aborted)return;games.value=visibleGames(data.games||[]);total.value=Number(data.total)||0;pages.value=Number(data.pages)||0;}catch(e){if(e.name!=='AbortError'){games.value=[];ElMessage.error(e.message);}}finally{if(gameRequestController===controller){gameRequestController=null;loading.value=false;}}}
async function changePageSize(value) { pageSize.value=value; await loadGames(1); }
function saveLocalPrefs(){try{localStorage.setItem('steamdeals.prefs.v1',JSON.stringify({tab:activeTab.value,sort:sort.value,region:region.value}));}catch{}}
async function savePrefs(){saveLocalPrefs();if(!user.value)return;try{await request('/api/prefs',{method:'POST',body:JSON.stringify({tab:activeTab.value,sort:sort.value,only_discount:false})});}catch{}}
async function setTab(value){activeTab.value=value;await savePrefs();await loadGames(1);}
async function changeSort(){await savePrefs();await loadGames(1);}
async function changeRegion(){saveLocalPrefs();await loadGames(1);}
async function loadUser(){try{const d=await request('/api/me');user.value=d.user||null;const local=(()=>{try{return JSON.parse(localStorage.getItem('steamdeals.prefs.v1')||'{}');}catch{return {};}})();region.value=local.region||'cn';if(user.value){guestGameFlags.value={};try{localStorage.removeItem(guestFlagsStorageKey);}catch{}if(detailVisible.value&&detail.value?.game)await openDetail(detail.value.game);activeTab.value=d.prefs?.tab??'all';sort.value=d.prefs?.sort??'discount';}else{activeTab.value=local.tab||'all';sort.value=local.sort||'discount';}}catch{user.value=null;}}
async function loadNotices() { try { const d=await request('/api/announcements'); notices.value=Array.isArray(d.announcements)?d.announcements:(Array.isArray(d)?d:[]); } catch { notices.value=[]; } }
function dismissNotice(id){noticeDismissed.value.add(id);try{localStorage.setItem('steamdeals.notice-hidden',JSON.stringify([...noticeDismissed.value]));}catch{}}
async function loadCaptcha(){try{const data=await request('/api/captcha');captchaToken.value=data.token||'';captchaImage.value=data.svg?`data:image/svg+xml;charset=utf-8,${encodeURIComponent(data.svg)}`:'';}catch{captchaToken.value='';captchaImage.value='';}}
async function login() { loginError.value='';loginLoading.value=true;try { await request('/api/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value,captchaToken:captchaToken.value,captchaAnswer:captchaAnswer.value})});await loadUser();loginVisible.value=false;password.value='';captchaAnswer.value='';await loadGames(1); } catch(e){loginError.value=e.message;captchaAnswer.value='';await loadCaptcha();}finally{loginLoading.value=false;} }
async function requestEmailCode(){loginError.value='';try{const d=await request('/api/auth/email/request',{method:'POST',body:JSON.stringify({email:email.value.trim(),purpose:loginMode.value==='reset'?'reset':'login'})});loginError.value=d.hint||'如果邮箱已绑定且可用，验证码将发送到该邮箱';codeCooldown.value=60;clearInterval(cooldownTimer);cooldownTimer=setInterval(()=>{codeCooldown.value--;if(codeCooldown.value<=0)clearInterval(cooldownTimer);},1000);}catch(e){loginError.value=e.message;}}
async function verifyEmail(){loginError.value='';loginLoading.value=true;try{const purpose=loginMode.value==='reset'?'reset':'login';const payload={email:email.value.trim(),code:emailCode.value.trim(),purpose};if(purpose==='reset')payload.password=newPassword.value;const d=await request('/api/auth/email/verify',{method:'POST',body:JSON.stringify(payload)});if(purpose==='reset'){loginError.value=d.message||'密码已重置，请使用新密码登录';loginMode.value='password';password.value='';await loadCaptcha();return;}await loadUser();loginVisible.value=false;emailCode.value='';await loadGames(1);}catch(e){loginError.value=e.message;}finally{loginLoading.value=false;}}
async function logout() { try { await request('/api/logout',{method:'POST',body:'{}'}); } finally { user.value=null;activeTab.value='all';await loadGames(1); } }
async function openDetail(game){detailVisible.value=true;detailLoading.value=true;detail.value=null;watchExists.value=false;watchTarget.value='';try{const path=game.steam_appid?`/api/games/${game.steam_appid}`:`/api/games/by-id/${game.id}`;detail.value=await request(`${path}?region=${encodeURIComponent(region.value)}`);if(!user.value){const flags=guestGameFlags.value[String(detail.value.game.id)]||{};detail.value.game={...detail.value.game,interested:typeof flags.interested==='boolean'?flags.interested:null,owned:flags.owned===true};}if(user.value?.role==='admin'){const w=await request('/api/admin/watchlist').catch(()=>({watches:[]}));const found=(w.watches||[]).find(x=>Number(x.game_id)===Number(detail.value.game.id));if(found){watchExists.value=true;watchTarget.value=found.target_cents==null?'':(found.target_cents/100).toFixed(2);}}}catch(e){ElMessage.error(e.message);detailVisible.value=false;}finally{detailLoading.value=false;}}
function regionName(code){return regions.find(r=>r.code===code)?.label||code||'—';}
function isInterested(game){return user.value?game?.user_interested===true:game?.interested===true;}
async function toggleFlag(kind){if(!detail.value?.game)return;await toggleGameFlag(detail.value.game,kind);}
async function toggleGameFlag(game,kind){const id=String(game.id);const current=kind==='interested'?isInterested(game):game.owned===true;const value=!current;if(!user.value){guestGameFlags.value={...guestGameFlags.value,[id]:{...(guestGameFlags.value[id]||{}),[kind]:value}};try{localStorage.setItem(guestFlagsStorageKey,JSON.stringify(guestGameFlags.value));}catch{ElMessage.warning('浏览器无法保存本地标记');}if(detail.value?.game?.id===game.id)detail.value={...detail.value,game:{...detail.value.game,[kind]:value}};await loadGames(page.value);return;}const body={[kind]:value};const path=game.steam_appid?`/api/games/${game.steam_appid}/flags`:`/api/games/id/${game.id}/flags`;try{await request(path,{method:'POST',body:JSON.stringify(body)});if(detail.value?.game?.id===game.id){const refreshed=await request(`${game.steam_appid?`/api/games/${game.steam_appid}`:`/api/games/by-id/${game.id}`}?region=${region.value}`);detail.value=refreshed;}await loadGames(page.value);}catch(e){ElMessage.error(e.message);}}
async function saveWatch(){if(!detail.value?.game)return;const raw=watchTarget.value.trim();const targetCents=raw===''?null:Math.round(Number(raw)*100);if(targetCents!==null&&(!Number.isFinite(targetCents)||targetCents<0))return ElMessage.warning('目标价不合法');try{await request('/api/admin/watchlist',{method:'POST',body:JSON.stringify({gameId:detail.value.game.id,targetCents})});watchExists.value=true;ElMessage.success('到价提醒已保存');}catch(e){ElMessage.error(e.message);}}
async function deleteWatch(){try{await request(`/api/admin/watchlist/${detail.value.game.id}`,{method:'DELETE'});watchExists.value=false;watchTarget.value='';ElMessage.success('提醒已取消');}catch(e){ElMessage.error(e.message);}}
onMounted(async()=>{try{noticeDismissed.value=new Set(JSON.parse(localStorage.getItem('steamdeals.notice-hidden')||'[]'));const p=JSON.parse(localStorage.getItem('steamdeals.prefs.v1')||'{}');activeTab.value=p.tab||'all';sort.value=p.sort||'discount';region.value=p.region||'cn';const flags=JSON.parse(localStorage.getItem(guestFlagsStorageKey)||'{}');guestGameFlags.value=flags&&typeof flags==='object'&&!Array.isArray(flags)?flags:{};}catch{}await loadUser();await Promise.all([loadGames(),loadNotices()]);});
onBeforeUnmount(()=>{clearInterval(cooldownTimer);gameRequestController?.abort();});
